 * @param {nsIInputStream} stream - Input stream containing the data chunk.
 * @param {integer} offset - Number of bytes that were sent in previous
 *   onDataAvailable calls for this request. In other words, the sum of all
 *   previous count parameters
 * @param {integer} count - Number of bytes available in the stream. May not be 0.
 */
onDataAvailable(req, stream, offset, count) {
  // get data from libmime
  if (!this.initOk) {
    return;
  }
  this.inStream.init(stream);

  if (count > 0) {
    var data = this.inStream.read(count);

    if (this.outputRaw) {
      this.cacheData(data);
      return;
    }

    if (this.mimePartCount == 0 && this.dataIsBase64 === null) {
      // try to determine if this could be a base64 encoded message part
      this.dataIsBase64 = this.isBase64Encoding(data);
    }

    if (!this.dataIsBase64) {
      if (data.search(/[\r\n][^\r\n]+[\r\n]/) >= 0) {
        // process multi-line data line by line
        const lines = data.replace(/\r\n/g, "\n").split(/\n/);

        for (let i = 0; i < lines.length; i++) {
          this.processData(lines[i] + "\r\n");
        }
      } else {
        this.processData(data);
      }
    } else {
      this.base64Cache += data;
    }
  }
},
